<?php
require_once __DIR__.'/_lib.php';
exigirSuperadmin();$p=periodoActivo();if(!$p)redir('modulos/votaciones/index.php');$e=eleccionPeriodo((int)$p['id']);if(!$e){flash('error','No existe proceso electoral.');redir('modulos/votaciones/index.php');}$eid=(int)$e['id'];
$seccion=(string)($_GET['seccion']??'todas');if(!in_array($seccion,['todas','matutina','vespertina'],true))$seccion='todas';
$sql="SELECT c.id,c.nombre,c.propuesta,c.foto,c.seccion,COUNT(v.id) votos FROM eleccion_candidatos c LEFT JOIN eleccion_votos v ON v.candidato_id=c.id WHERE c.eleccion_id=? AND c.activo=1";
if($seccion!=='todas'){$sql.=' AND c.seccion=? GROUP BY c.id ORDER BY votos DESC,c.nombre';$stmt=$conexion->prepare($sql);$stmt->bind_param('is',$eid,$seccion);}else{$sql.=' GROUP BY c.id ORDER BY c.seccion,votos DESC,c.nombre';$stmt=$conexion->prepare($sql);$stmt->bind_param('i',$eid);} $stmt->execute();$candidatos=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();
$datos=[];foreach(['matutina','vespertina'] as $s){$pob=poblacionEleccion($eid,$s);$v=votosEleccion($eid,$s);$datos[$s]=['poblacion'=>$pob,'votos'=>$v,'pendientes'=>max(0,$pob-$v),'participacion'=>$pob?round($v/$pob*100,1):0];}
$maxPorSeccion=['matutina'=>0,'vespertina'=>0];foreach($candidatos as $c){$s=$c['seccion'];$maxPorSeccion[$s]=max($maxPorSeccion[$s],(int)$c['votos']);}
$tituloPagina='Resultados electorales';$subtituloPagina=$e['titulo'].' · '.$p['nombre'];require APP_ROOT.'/partials/header.php';
?>
<div class="toolbar"><div class="actions"><a class="btn btn-secondary" href="<?=e(url('modulos/votaciones/index.php'))?>">← Votaciones</a><a class="btn <?=$seccion==='todas'?'btn-primary':'btn-secondary'?>" href="?seccion=todas">Todos</a><a class="btn <?=$seccion==='matutina'?'btn-primary':'btn-secondary'?>" href="?seccion=matutina">Matutina</a><a class="btn <?=$seccion==='vespertina'?'btn-primary':'btn-secondary'?>" href="?seccion=vespertina">Vespertina</a></div><div class="actions"><a class="btn btn-secondary" href="<?=e(url('modulos/votaciones/resultados_csv.php?seccion='.urlencode($seccion)))?>">CSV nominal</a><a class="btn btn-success" href="<?=e(url('modulos/votaciones/resultados_pdf.php?seccion='.urlencode($seccion)))?>">Descargar PDF</a></div></div>
<div class="notice" style="margin-bottom:16px"><strong>CSV nominal (;):</strong> contiene quién votó, quién no votó y el candidato elegido por cada estudiante. Usa punto y coma como delimitador, está restringido al Superadministrador y queda registrado en Auditoría.</div>
<div class="grid cols-4"><div class="card metric"><span>Matutina · población</span><strong><?=$datos['matutina']['poblacion']?></strong><small class="muted"><?=$datos['matutina']['votos']?> votos · <?=$datos['matutina']['participacion']?>%</small></div><div class="card metric"><span>Vespertina · población</span><strong><?=$datos['vespertina']['poblacion']?></strong><small class="muted"><?=$datos['vespertina']['votos']?> votos · <?=$datos['vespertina']['participacion']?>%</small></div><div class="card metric"><span>Total votantes</span><strong><?=($datos['matutina']['poblacion']+$datos['vespertina']['poblacion'])?></strong></div><div class="card metric"><span>Votos emitidos</span><strong><?=($datos['matutina']['votos']+$datos['vespertina']['votos'])?></strong></div></div>
<h2 class="section-title">Candidatos y votos</h2><div class="vote-admin-grid">
<?php foreach($candidatos as $c):?><div class="card candidate-admin-card result-card <?=((int)$c['votos']>0&&(int)$c['votos']===$maxPorSeccion[$c['seccion']])?'winner-card':''?>"><?php $fu=fotoCandidatoUrl($c['foto']);?><?php if($fu):?><img src="<?=e($fu)?>" alt="Fotografía de <?=e($c['nombre'])?>"><?php else:?><div class="candidate-placeholder">Sin foto</div><?php endif;?><div><span class="badge"><?=e(ucfirst($c['seccion']))?></span><h3><?=e(strtoupper($c['nombre']))?></h3><p class="muted"><?=e($c['propuesta'])?></p><?php if((int)$c['votos']>0&&(int)$c['votos']===$maxPorSeccion[$c['seccion']]):?><span class="badge good">Mayor votación</span><?php endif;?><div class="result-votes"><?=(int)$c['votos']?> <small>votos</small></div></div></div><?php endforeach;?>
<?php if(!$candidatos):?><div class="card empty">No existen candidatos para el filtro seleccionado.</div><?php endif;?></div>
<div class="card" style="margin-top:18px"><h3>Control de participación</h3><div class="table-wrap"><table class="table table-responsive-cards"><thead><tr><th>Sección</th><th>Población habilitada</th><th>Votos emitidos</th><th>Pendientes</th><th>Participación</th></tr></thead><tbody><?php foreach($datos as $s=>$d):?><tr><td><strong><?=e(ucfirst($s))?></strong></td><td><?=$d['poblacion']?></td><td><?=$d['votos']?></td><td><?=$d['pendientes']?></td><td><?=$d['participacion']?>%</td></tr><?php endforeach;?></tbody></table></div></div>
<?php require APP_ROOT.'/partials/footer.php';?>
